-- Generated by the run's orchestrator; old or unavailable agents keep the title fallback.
ALTER TABLE workflow_runs ADD COLUMN task_summary text NOT NULL DEFAULT ''
    CHECK (char_length(task_summary) <= 80);
COMMENT ON COLUMN workflow_runs.task_summary IS
    'Short task summary supplied by the orchestrator. Empty until available; fall back to title.';

-- Queue readers see the same task label as the run pages, including queued startup retries.
CREATE OR REPLACE VIEW workflow_run_queue WITH (security_invoker = true) AS
SELECT id AS run_id, account_id, host, workflow_id,
       coalesce(nullif(task_summary, ''), title) AS title,
       row_number() OVER (PARTITION BY host ORDER BY created_at, id) AS position,
       queue_reason, created_at AS queued_at
FROM workflow_runs
WHERE status = 'queued' OR start_retry_queued;
